#include <bits/stdc++.h>using namespace std;using ll = long long; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;     while (t--) {        int n;        cin >> n;         ll global_min = LLONG_MAX;        ll min_second = LLONG_MAX;        ll sum_second = 0;         for (int i = 0; i < n; i++) {            int m;            cin >> m;             vector<ll> a(m);            for (auto &x : a) cin >> x;             sort(a.begin(), a.end());             ll min1 = a[0];            ll min2 = a[1];             global_min = min(global_min, min1);            min_second = min(min_second, min2);            sum_second += min2;        }         ll ans = sum_second - min_second + global_min;         cout << ans << "\n";    }}